// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    // fuzzed params: amount to send and caller address
    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(amount <= VALUE_CAP);
        // keep amount in a reasonable range so vm.deal can fund the caller
        amount = bound(amount, 0, 100 ether);
        // caller must be a non-zero address
        vm.assume(caller != address(0));

        vm.deal(caller, amount);
        bool ok;
        // perform the low-level call to trigger fallback from `caller` with `amount`
        vm.prank(caller);
        (bool success, ) = address(c).call{value: amount}("");
        ok = success;

        // Reference contract: succeeds iff msg.value == 10 ether for ANY caller/amount
        // Single assertion reading c's observable behavior (call success) — reference satisfies for all inputs,
        // mutant requiring 5 ether will differ for some fuzzed inputs (e.g., amount == 5 ether yields success there but not here).
        assertTrue(ok == (amount == 10 ether));
    }
}
